cat > /app/output/sim_components.py <<'PY'
import numpy as np
from PIL import Image,ImageDraw
from scipy import ndimage as ndi
im=np.array(Image.open('/app/target.png'),dtype=np.float32)
refs=np.array([[241,221,164],[199,210,173],[152,185,169],[125,155,152],[125,143,96],[94,120,130],[62,85,104],[55,87,66],[96,61,55],[34,56,84],[248,244,236]],dtype=np.float32)
l=((im[:,:,None,:]-refs[None,None,:,:])**2).sum(3).argmin(2).astype(np.uint8); H,W=l.shape
# vertical same-class thickness
up=np.ones((H,W),np.uint16); dn=np.ones((H,W),np.uint16)
for y in range(1,H):up[y]=np.where(l[y]==l[y-1],up[y-1]+1,1)
for y in range(H-2,-1,-1):dn[y]=np.where(l[y]==l[y+1],dn[y+1]+1,1)

def make(step,threshold=20,offset=0,order=None):
 strokes=[]
 for c in range(10):
  cc,n=ndi.label(l==c,structure=np.ones((3,3)));sizes=np.bincount(cc.ravel());
  for k in range(1,n+1):
   area=int(sizes[k]);
   if area<threshold:continue
   ys,xs=np.where(cc==k); ymin,ymax=ys.min(),ys.max(); xlo,xhi=xs.min(),xs.max()
   # fixed row spacing, centered on bbox y (row sequence global offset)
   first=ymin+((offset-ymin)%step)
   rows=list(range(first,ymax+1,step))
   if not rows: rows=[int(np.median(ys))]
   segs=[]
   for y in rows:
    xx=np.flatnonzero(cc[y,xlo:xhi+1]==k)+xlo
    if len(xx)==0:continue
    # contiguous runs
    breaks=np.where(np.diff(xx)>1)[0]+1
    for run in np.split(xx,breaks):
     if len(run)==0:continue
     x0,x1=int(run[0]),int(run[-1]); thick=float(np.median(up[y,x0:x1+1]+dn[y,x0:x1+1]-1))
     width=9 if thick<16 else (20 if thick<32 else 42)
     segs.append((y,x0,x1,width,thick))
   # if no segments, pick longest row (centroid)
   if not segs:
    yy=int(np.median(ys));xx=np.flatnonzero(cc[yy,xlo:xhi+1]==k)+xlo
    if not len(xx):
     # choose row with max component pixels
     rr=np.bincount(ys-ymin); yy=int(ymin+np.argmax(rr));xx=np.flatnonzero(cc[yy,xlo:xhi+1]==k)+xlo
    thick=float(np.median(up[yy,xx]+dn[yy,xx]-1)); width=9 if thick<16 else (20 if thick<32 else 42)
    segs=[(yy,int(xx[0]),int(xx[-1]),width,thick)]
   strokes.extend((c,k,*s,area) for s in segs)
 # comps count and predicted image; draw all stripe tracks
 canvas=Image.new('L',(W,H),10);dr=ImageDraw.Draw(canvas)
 if order is None: order=list(range(10))
 for c in order:
  for sc,k,y,x0,x1,w,t,area in strokes:
   if sc==c:dr.line((x0,y,x1,y),fill=c,width=w)
 pred=np.array(canvas); fg=l<10; pf=pred<10
 iou=(fg&pf).sum()/(fg|pf).sum(); acc=(pred[fg]==l[fg]).mean()
 err=np.linalg.norm(refs[pred]-refs[l],axis=2); active=fg|pf
 de=float(err[active].mean());p90=float(np.quantile(err[active],.9))
 # 4.5px Gaussian blur delta mean over active target expanded, RGB mean
 from scipy.ndimage import gaussian_filter
 tarblur=gaussian_filter(refs[l],sigma=(4.5,4.5,0)); preblur=gaussian_filter(refs[pred],sigma=(4.5,4.5,0));
 blurerr=np.linalg.norm(tarblur-preblur,axis=2); print('  blurmean',float(blurerr[active].mean()))
 return len(set((c,k) for c,k,*_ in strokes)),len(strokes),iou,acc,de,p90, pred,strokes
if __name__=='__main__':
 for th in [5,10,20,30,50,100]:
  for step in [12,16,20,24,28,32,40]:
   n,ns,iou,acc,de,p90,pred,st=make(step,th,offset=step//2)
   if n<=377:print('th',th,'step',step,'contact',n,'scanlines',ns,'iou',round(iou,4),'acc',round(acc,4),'de',round(de,2),'p90',round(p90,1))
   if th==20 and step==20:Image.fromarray(refs[pred].astype('uint8')).save('/app/output/pred_components.png')
